 "content": "from collections import deque


def transform(grid):
    """Color centers of solid 3x3 blocks with the marker color in their 1-region."""
    h, w = len(grid), len(grid[0])
    labels = [[-1] * w for _ in range(h)]
    component_markers = {}
    component_id = 0

    # Markers are embedded in the foreground, so treat every nonzero cell as
    # part of the same foreground mask when finding 4-connected components.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or labels[r][c] != -1:
                continue
            q = deque([(r, c)])
            labels[r][c] = component_id
            markers = set()
            while q:
                y, x = q.popleft()
                if grid[y][x] not in (0, 1):
                    markers.add(grid[y][x])
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and labels[ny][nx] == -1:
                        labels[ny][nx] = component_id
                        q.append((ny, nx))
            component_markers[component_id] = markers
            component_id += 1

    out = [row[:] for row in grid]
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if all(grid[y][x] != 0
                   for y in range(r - 1, r + 2)
                   for x in range(c - 1, c + 2)):
                colors = component_markers[labels[r][c]]
                if len(colors) == 1:
                    out[r][c] = next(iter(colors))
                elif colors:
                    # If a foreground region contains multiple markers, use
                    # the closest marker to the block center.
                    nearest = min(
                        ((abs(r - mr) + abs(c - mc), color)
                         for mr in range(h) for mc in range(w)
                         if (color := grid[mr][mc]) in colors),
                        key=lambda item: (item[0], item[1]),
                    )
                    out[r][c] = nearest[1]
    return out
